fault_script:
#!/bin/bash
set -euo pipefail
exec >>/home/phat/ml-experiments/90a0d5bd4531/fault.log 2>&1
echo FAULT_BEFORE $(date -u +%s)
nft add table inet mlv2_90a0d5bd4531
nft 'add chain inet mlv2_90a0d5bd4531 input { type filter hook input priority 0; policy accept; }'
nft add rule inet mlv2_90a0d5bd4531 input ip saddr 192.168.56.10 tcp dport 80 counter drop
nft list table inet mlv2_90a0d5bd4531
echo FAULT_VERIFIED $(date -u +%s)

rollback_script:
#!/bin/bash
set -euo pipefail
exec >>/home/phat/ml-experiments/90a0d5bd4531/rollback.log 2>&1
echo ROLLBACK_BEFORE $(date -u +%s)
tables="$(nft list tables)"
if printf '%s\n' "$tables" | grep -Fxq 'table inet mlv2_90a0d5bd4531'; then
  nft delete table inet mlv2_90a0d5bd4531
fi
echo ROLLBACK_AFTER $(date -u +%s)
